exercises.solution:
def dichotomie(tableau, cible):
    debut, fin = 0, len(tableau) - 1
    while debut <= fin:
        milieu = (debut + fin) // 2
        if tableau[milieu] == cible:
            return milieu
        elif tableau[milieu] < cible:
            debut = milieu + 1
        else:
            fin = milieu - 1
    return -1

