#include <stdio.h>

int main(void) {
    int n = 5;
    int c = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            c++;
        }
    }
    printf("%d\n", c);
    return 0;
}

public static int dichotomie(int[] t, int cible) {
    int debut = 0;
    int fin = t.length - 1;
    while (debut <= fin) {
        int milieu = (debut + fin) / 2;
        if (t[milieu] == cible) {
            return milieu;
        } else if (t[milieu] < cible) {
            debut = milieu;          // <-- ligne suspecte
        } else {
            fin = milieu - 1;
        }
    }
    return -1;
}
